import 'server-only';

import { Prisma, type UserRole, type UserType } from '@prisma/client';

import { getDb } from '@/server/db';

export interface CreateUserRecord {
  openfortUserId: string;
  email?: string | null;
  firstName?: string | null;
  lastName?: string | null;
  phoneNumber?: string | null;
  companyName?: string | null;
  type: UserType;
  role: UserRole;
}

export function findUserByOpenfortId(openfortUserId: string) {
  return getDb().user.findFirst({
    where: {
      openfortUserId,
      deletedAt: null,
    },
  });
}

export async function openfortUserExists(openfortUserId: string) {
  const count = await getDb().user.count({
    where: {
      openfortUserId,
      deletedAt: null,
    },
  });

  return count > 0;
}

export async function createUser(record: CreateUserRecord) {
  return getDb().$transaction(async (tx) => {
    const user = await tx.user.create({
      data: {
        openfortUserId: record.openfortUserId,
        email: record.email,
        firstName: record.firstName,
        lastName: record.lastName,
        phoneNumber: record.phoneNumber,
        type: record.type,
        role: record.role,
        status: 'pending_kyc',
      },
    });

    if (record.type === 'organization' && record.companyName) {
      await tx.userOrganization.create({
        data: {
          userId: user.id,
          name: record.companyName,
        },
      });
    }

    return user;
  });
}

export function isUserUniqueConstraintError(error: unknown) {
  return (
    error instanceof Prisma.PrismaClientKnownRequestError &&
    error.code === 'P2002'
  );
}

import 'server-only';

import { ApiError } from '@/server/http';

export function requireBearerToken(request: Request) {
  const authorization = request.headers.get('authorization') ?? '';
  const prefix = 'Bearer ';

  if (!authorization.startsWith(prefix)) {
    throw new ApiError(
      'BAD_REQUEST',
      'Authorization bearer token is required.'
    );
  }

  const token = authorization.slice(prefix.length).trim();

  if (!token) {
    throw new ApiError(
      'BAD_REQUEST',
      'Authorization bearer token is required.'
    );
  }

  return token;
}

import 'server-only';

import type { UserRole, UserType } from '@prisma/client';
import { jwtVerify, SignJWT } from 'jose';

import { requireServerEnv } from '@/server/env';

interface AppAccessTokenClaims {
  userId: string;
  sessionId: string;
  kycVerified: boolean;
  kybVerified: boolean;
  type: UserType;
  role: UserRole;
}

function getJwtSecret() {
  const env = requireServerEnv(['auth']);
  return new TextEncoder().encode(env.auth.jwtSecret!);
}

export async function signAppAccessToken(
  claims: AppAccessTokenClaims,
  expiresAt: Date
) {
  const env = requireServerEnv(['auth']);
  const jwt = new SignJWT({
    session_id: claims.sessionId,
    kyc_verified: claims.kycVerified,
    kyb_verified: claims.kybVerified,
    type: claims.type,
    role: claims.role,
  })
    .setProtectedHeader({ alg: 'HS256' })
    .setSubject(claims.userId)
    .setAudience(env.auth.jwtAudience)
    .setIssuedAt()
    .setExpirationTime(Math.floor(expiresAt.getTime() / 1000));

  if (env.auth.jwtIssuer) {
    jwt.setIssuer(env.auth.jwtIssuer);
  }

  return jwt.sign(getJwtSecret());
}

export async function verifyAppAccessToken(token: string) {
  const env = requireServerEnv(['auth']);
  const result = await jwtVerify(token, getJwtSecret(), {
    audience: env.auth.jwtAudience,
    issuer: env.auth.jwtIssuer,
  });

  if (!result.payload.sub || typeof result.payload.session_id !== 'string') {
    throw new Error('Invalid app access token claims');
  }

  return {
    userId: result.payload.sub,
    sessionId: result.payload.session_id,
  };
}

import 'server-only';

import { NextResponse } from 'next/server';

import {
  ApiError,
  internalServerError,
  isApiError,
  jsonError,
} from './api-error';

export interface ApiSuccessBody<T> {
  code: 'OK';
  data: T;
}

export function jsonOk<T>(data: T, init?: ResponseInit) {
  return NextResponse.json<ApiSuccessBody<T>>(
    { code: 'OK', data },
    { status: init?.status ?? 200, headers: init?.headers }
  );
}

export function jsonNoContent() {
  return new NextResponse(null, { status: 204 });
}

export function handleApiError(error: unknown) {
  if (isApiError(error)) {
    return jsonError(error);
  }

  return jsonError(internalServerError());
}

export function badRequest(message: string, detail?: string) {
  return new ApiError('BAD_REQUEST', message, { detail });
}

export function unauthorized(message = 'Unauthorized') {
  return new ApiError('UNAUTHORIZED', message);
}

import 'server-only';

import { NextResponse } from 'next/server';

export type ApiErrorCode =
  | 'BAD_REQUEST'
  | 'UNAUTHORIZED'
  | 'FORBIDDEN'
  | 'NOT_FOUND'
  | 'CONFLICT'
  | 'VALIDATION_ERROR'
  | 'INTERNAL_SERVER_ERROR'
  | 'SERVICE_UNAVAILABLE';

export interface ApiErrorBody {
  code: ApiErrorCode;
  message: string;
  detail?: string;
  fields?: Record<string, string>;
}

export class ApiError extends Error {
  readonly code: ApiErrorCode;
  readonly status: number;
  readonly detail?: string;
  readonly fields?: Record<string, string>;

  constructor(
    code: ApiErrorCode,
    message: string,
    options: {
      status?: number;
      detail?: string;
      fields?: Record<string, string>;
      cause?: unknown;
    } = {}
  ) {
    super(message, { cause: options.cause });
    this.name = 'ApiError';
    this.code = code;
    this.status = options.status ?? statusByCode[code];
    this.detail = options.detail;
    this.fields = options.fields;
  }
}

const statusByCode: Record<ApiErrorCode, number> = {
  BAD_REQUEST: 400,
  UNAUTHORIZED: 401,
  FORBIDDEN: 403,
  NOT_FOUND: 404,
  CONFLICT: 409,
  VALIDATION_ERROR: 422,
  INTERNAL_SERVER_ERROR: 500,
  SERVICE_UNAVAILABLE: 503,
};

export function isApiError(error: unknown): error is ApiError {
  return error instanceof ApiError;
}

export function toApiErrorBody(error: ApiError): ApiErrorBody {
  return {
    code: error.code,
    message: error.message,
    ...(error.detail ? { detail: error.detail } : {}),
    ...(error.fields ? { fields: error.fields } : {}),
  };
}

export function jsonError(error: ApiError) {
  return NextResponse.json(toApiErrorBody(error), { status: error.status });
}

export function internalServerError() {
  return new ApiError('INTERNAL_SERVER_ERROR', 'Internal server error');
}

