import 'server-only';

import Openfort from '@openfort/openfort-node';

import { ApiError } from '@/server/http';
import { logger } from '@/server/logger';
import { requireServerEnv } from '@/server/env';

export interface VerifiedOpenfortSession {
  user: {
    id: string;
    email?: string | null;
    name?: string | null;
    phoneNumber?: string | null;
  };
  session: {
    id?: string | null;
    expiresAt?: string | null;
  };
}

let cachedClient: Openfort | undefined;

function getOpenfortClient() {
  if (cachedClient) return cachedClient;

  const { openfort } = requireServerEnv(['openfort']);
  cachedClient = new Openfort(openfort.secretKey!, {
    basePath: openfort.baseUrl,
    publishableKey: openfort.publishableKey,
  });

  return cachedClient;
}

function normalizeOpenfortSession(session: unknown): VerifiedOpenfortSession {
  if (!session || typeof session !== 'object') {
    throw new ApiError('UNAUTHORIZED', 'Invalid Openfort access token.');
  }

  const value = session as {
    user?: {
      id?: unknown;
      email?: unknown;
      name?: unknown;
      phoneNumber?: unknown;
    };
    session?: {
      id?: unknown;
      expiresAt?: unknown;
    };
  };
  const userId = value.user?.id;

  if (typeof userId !== 'string' || !userId.trim()) {
    throw new ApiError('UNAUTHORIZED', 'Invalid Openfort access token.');
  }

  return {
    user: {
      id: userId,
      email:
        typeof value.user?.email === 'string' ? value.user.email : undefined,
      name: typeof value.user?.name === 'string' ? value.user.name : undefined,
      phoneNumber:
        typeof value.user?.phoneNumber === 'string'
          ? value.user.phoneNumber
          : undefined,
    },
    session: {
      id: typeof value.session?.id === 'string' ? value.session.id : undefined,
      expiresAt:
        typeof value.session?.expiresAt === 'string'
          ? value.session.expiresAt
          : undefined,
    },
  };
}

export async function verifyOpenfortAccessToken(accessToken: string) {
  try {
    const session = await getOpenfortClient().iam.getSession({ accessToken });
    return normalizeOpenfortSession(session);
  } catch (error) {
    if (error instanceof ApiError) throw error;

    logger.warn({ err: error }, 'Openfort session verification failed');
    throw new ApiError('UNAUTHORIZED', 'Invalid Openfort access token.');
  }
}

package handler

import (
	"context"
	"net/http"
	"strings"
	"time"

	"github.com/InfraFund-net7/backpro/internal/application/auth/dto"
	authctx "github.com/InfraFund-net7/backpro/internal/common/types/auth"
	"github.com/InfraFund-net7/backpro/internal/common/types/client"
	"github.com/InfraFund-net7/backpro/internal/domain/auth/service"
	"github.com/InfraFund-net7/backpro/internal/domain/shared"
	"github.com/InfraFund-net7/backpro/internal/domain/user/object"
	restcfg "github.com/InfraFund-net7/backpro/internal/interfaces/rest"
	"github.com/InfraFund-net7/backpro/internal/interfaces/rest/input"
	"github.com/InfraFund-net7/backpro/internal/interfaces/rest/output"
	"github.com/InfraFund-net7/backpro/pkg/errs"
	"github.com/google/uuid"
)

type AuthHandler struct {
	svc         service.AuthService
	development bool
	cookieCfg   authCookieConfig
}

type authCookieConfig struct {
	sameSite http.SameSite
	domain   string
}

func NewAuthHandler(cfg *restcfg.Config, svc service.AuthService) *AuthHandler {
	return &AuthHandler{
		svc:         svc,
		development: cfg.Development,
		cookieCfg: authCookieConfig{
			sameSite: parseSameSite(cfg.CookieSameSite),
			domain:   strings.TrimSpace(cfg.CookieDomain),
		},
	}
}

func (a *AuthHandler) CheckOpenfortUser(ctx context.Context,
	in *input.OpenfortCheckInput,
) (*output.SuccessOutput[*dto.OpenfortCheckResp], error) {
	accessToken := extractBearerToken(in.Authorization)
	if accessToken == "" {
		return nil, output.NewErrorOutput(
			errs.NewAppError(errs.BadRequest, "Authorization bearer token is required.", 400),
		)
	}

	resp, err := a.svc.CheckOpenfortUser(ctx, accessToken)
	if err != nil {
		return nil, output.NewErrorOutput(err)
	}

	return output.NewSuccessOutput(resp), nil
}

func (a *AuthHandler) Exchange(ctx context.Context,
	in *input.OpenfortExchangeInput,
) (*output.LoginOutput, error) {
	info := client.GetClientInfo(ctx)

	req := &dto.OpenfortExchangeReq{
		AccessToken:      extractBearerToken(in.Authorization),
		FirstName:        in.Body.FirstName,
		LastName:         in.Body.LastName,
		OrganizationName: in.Body.OrganizationName,
		PhoneNumber:      shared.NewPhoneNumber(in.Body.PhoneNumber),
		Email:            shared.NewEmail(in.Body.Email),
		Type:             object.UserType(in.Body.Type),
		Role:             object.UserRole(in.Body.Role),
	}

	if req.AccessToken == "" {
		return nil, output.NewErrorOutput(
			errs.NewAppError(errs.BadRequest, "Authorization bearer token is required.", 400),
		)
	}

	attachClientInfo(info, &req.Audit)

	resp, err := a.svc.Exchange(ctx, req)
	if err != nil {
		return nil, output.NewErrorOutput(err)
	}

	return a.createLoginOutput(resp), nil
}

func (a *AuthHandler) Me(ctx context.Context,
	_ *input.CurrentUserInput,
) (*output.SuccessOutput[*dto.MeResp], error) {
	userID, err := authorizedUserID(ctx)
	if err != nil {
		return nil, err
	}

	resp, svcErr := a.svc.Me(ctx, userID)
	if svcErr != nil {
		return nil, output.NewErrorOutput(svcErr)
	}

	return output.NewSuccessOutput(resp), nil
}

func (a *AuthHandler) AccountStatus(ctx context.Context,
	_ *input.CurrentUserInput,
) (*output.SuccessOutput[*dto.AccountStatusResp], error) {
	userID, err := authorizedUserID(ctx)
	if err != nil {
		return nil, err
	}

	resp, svcErr := a.svc.AccountStatus(ctx, userID)
	if svcErr != nil {
		return nil, output.NewErrorOutput(svcErr)
	}

	return output.NewSuccessOutput(resp), nil
}

func (a *AuthHandler) KycStatus(ctx context.Context,
	_ *input.CurrentUserInput,
) (*output.SuccessOutput[*dto.KycStatusResp], error) {
	userID, err := authorizedUserID(ctx)
	if err != nil {
		return nil, err
	}

	resp, svcErr := a.svc.KycStatus(ctx, userID)
	if svcErr != nil {
		return nil, output.NewErrorOutput(svcErr)
	}

	return output.NewSuccessOutput(resp), nil
}

func (a *AuthHandler) RefreshAccessToken(ctx context.Context,
	in *input.RefreshTokenInput,
) (*output.SuccessOutput[*dto.RefreshAccessTokenResp], error) {
	resp, err := a.svc.RefreshAccessToken(ctx, in.RefreshToken)
	if err != nil {
		return nil, output.NewErrorOutput(err)
	}

	return output.NewSuccessOutput(resp), nil
}

func (a *AuthHandler) Logout(ctx context.Context,
	in *input.RefreshTokenInput,
) (*output.LogoutOutput, error) {
	if err := a.svc.Logout(ctx, in.RefreshToken); err != nil {
		return nil, output.NewErrorOutput(err)
	}

	return &output.LogoutOutput{
		Body:      output.NewSuccessEmptyOutput(),
		SetCookie: a.clearRefreshTokenCookie(),
	}, nil
}

func (a *AuthHandler) DeleteAccount(ctx context.Context,
	_ *input.CurrentUserInput,
) (*output.LogoutOutput, error) {
	userID, err := authorizedUserID(ctx)
	if err != nil {
		return nil, err
	}

	if svcErr := a.svc.DeleteAccount(ctx, userID); svcErr != nil {
		return nil, output.NewErrorOutput(svcErr)
	}

	return &output.LogoutOutput{
		Body:      output.NewSuccessEmptyOutput(),
		SetCookie: a.clearRefreshTokenCookie(),
	}, nil
}

func authorizedUserID(ctx context.Context) (uuid.UUID, error) {
	userInfo := authctx.GetUserInfoFromContext(ctx)
	if userInfo == nil {
		return uuid.Nil, output.NewErrorOutput(
			errs.NewAppError(errs.Unauthorized, "missing authorized user context", 401),
		)
	}

	return userInfo.UserID, nil
}

func attachClientInfo(info *client.Info, audit *dto.AuditReq) {
	if info == nil {
		return
	}
	audit.IPAddress = info.IP
	audit.UserAgent = info.UserAgent
	audit.Platform = info.Platform
	audit.Browser = info.Browser
	audit.Device = info.Device
}

func extractBearerToken(header string) string {
	const bearerPrefix = "Bearer "
	if !strings.HasPrefix(header, bearerPrefix) {
		return ""
	}

	return strings.TrimSpace(strings.TrimPrefix(header, bearerPrefix))
}

func (a *AuthHandler) createRefreshTokenCookie(token string, expiry time.Time) http.Cookie {
	cookie := http.Cookie{
		Name:     "refresh_token",
		Value:    token,
		Secure:   !a.development,
		HttpOnly: true,
		SameSite: a.cookieCfg.sameSite,
		Expires:  expiry,
		Path:     "/",
	}

	if a.cookieCfg.domain != "" {
		cookie.Domain = a.cookieCfg.domain
	}

	return cookie
}

func (a *AuthHandler) clearRefreshTokenCookie() http.Cookie {
	cookie := http.Cookie{
		Name:     "refresh_token",
		Value:    "",
		Secure:   !a.development,
		HttpOnly: true,
		SameSite: a.cookieCfg.sameSite,
		MaxAge:   -1,
		Path:     "/",
	}

	if a.cookieCfg.domain != "" {
		cookie.Domain = a.cookieCfg.domain
	}

	return cookie
}

func (a *AuthHandler) createLoginOutput(resp *dto.LoginResp) *output.LoginOutput {
	return &output.LoginOutput{
		SetCookie: a.createRefreshTokenCookie(resp.RefreshToken, resp.RefreshTokenExpiry),
		Body: output.SuccessResponse[*dto.LoginResp]{
			Data: resp,
		},
	}
}

func parseSameSite(mode string) http.SameSite {
	switch strings.ToLower(strings.TrimSpace(mode)) {
	case "strict":
		return http.SameSiteStrictMode
	case "none":
		return http.SameSiteNoneMode
	default:
		return http.SameSiteLaxMode
	}
}

package auth

import (
	"context"
	"strings"
	"time"

	"github.com/InfraFund-net7/backpro/internal/application/auth/dto"
	authentity "github.com/InfraFund-net7/backpro/internal/domain/auth/entity"
	"github.com/InfraFund-net7/backpro/internal/domain/auth/service"
	sessentity "github.com/InfraFund-net7/backpro/internal/domain/session/entity"
	sessobj "github.com/InfraFund-net7/backpro/internal/domain/session/object"
	sessrepo "github.com/InfraFund-net7/backpro/internal/domain/session/repository"
	"github.com/InfraFund-net7/backpro/internal/domain/shared"
	userentity "github.com/InfraFund-net7/backpro/internal/domain/user/entity"
	"github.com/InfraFund-net7/backpro/internal/domain/user/object"
	usrrepo "github.com/InfraFund-net7/backpro/internal/domain/user/repository"
	"github.com/InfraFund-net7/backpro/internal/infrastructure/external/openfort"
	"github.com/InfraFund-net7/backpro/pkg/crypto"
	"github.com/InfraFund-net7/backpro/pkg/errs"
	"github.com/InfraFund-net7/backpro/pkg/logger"
	"github.com/google/uuid"
)

var _ service.AuthService = (*AuthService)(nil)

type AuthService struct {
	userRepo usrrepo.UserRepo
	sessRepo sessrepo.SessionRepo

	lockoutSvc service.AccountLockoutService
	jwtSvc     service.JwtService
	openfort   openfort.SessionVerifier

	txn shared.Transactor
	cfg *Config

	logger *logger.SubLogger
}

func NewOpenfortAuthService(
	userRepo usrrepo.UserRepo,
	sessRepo sessrepo.SessionRepo,
	lockoutSvc service.AccountLockoutService,
	jwtSvc service.JwtService,
	txn shared.Transactor,
	openfortVerifier openfort.SessionVerifier,
	cfg *Config,
) *AuthService {
	return &AuthService{
		userRepo:   userRepo,
		sessRepo:   sessRepo,
		lockoutSvc: lockoutSvc,
		jwtSvc:     jwtSvc,
		openfort:   openfortVerifier,
		txn:        txn,
		cfg:        cfg,
		logger:     logger.NewBusinessLogger("auth"),
	}
}

func (a *AuthService) CheckOpenfortUser(ctx context.Context, accessToken string) (*dto.OpenfortCheckResp, error) {
	session, err := a.getOpenfortSession(ctx, accessToken)
	if err != nil {
		return nil, err
	}

	exists, err := a.userRepo.ExistsOpenfortUserID(ctx, session.User.ID)
	if err != nil {
		a.logger.Error("failed to check openfort user by id", "error", err.Error(), "openfort_user_id", session.User.ID)

		return nil, errs.NewAppError(errs.Database, "Failed to check user.", 500)
	}

	return &dto.OpenfortCheckResp{
		Exists: exists,
	}, nil
}

func (a *AuthService) Exchange(ctx context.Context, req *dto.OpenfortExchangeReq) (*dto.LoginResp, error) {
	session, err := a.getOpenfortSession(ctx, req.AccessToken)
	if err != nil {
		return nil, err
	}

	user, created, err := a.findOrCreateUser(ctx, req, session)
	if err != nil {
		return nil, err
	}

	if !created {
		if err = a.lockoutSvc.CheckAccountLock(ctx, user.ID); err != nil {
			a.logger.Warn("openfort exchange attempt on locked account", "user_id", user.ID)

			return nil, errs.NewAppError(errs.TooManyRequests, "Account locked. Try again later.", 429)
		}
	}

	sessID, rt, err := a.createSession(ctx, user.ID, req.Audit)
	if err != nil {
		a.logger.Error("failed to create session", "error", err.Error())

		return nil, errs.NewAppError(errs.Database, "Failed to create session.", 500)
	}

	accessToken, err := a.createToken(user.ID, sessID, user.KycVerified, user.KybVerified, user.Type, user.Role)
	if err != nil {
		a.logger.Error("failed to create token", "error", err.Error())

		return nil, errs.NewAppError(errs.Internal, "Failed to create access token.", 500)
	}

	if !created {
		if err = a.lockoutSvc.ResetAfterSuccessfulAuth(ctx, user.ID); err != nil {
			a.logger.Warn("failed to reset lockout after successful exchange",
				"error", err.Error(),
				"user_id", user.ID,
			)
		}
	}

	return &dto.LoginResp{
		UserID:             user.ID,
		AccessToken:        accessToken,
		RefreshToken:       rt,
		AccessTokenExpiry:  time.Now().Add(a.cfg.Jwt.AccessTokenTTL),
		RefreshTokenExpiry: time.Now().Add(a.cfg.AbsoluteExpiresDuration),
	}, nil
}

func (a *AuthService) Me(ctx context.Context, userID uuid.UUID) (*dto.MeResp, error) {
	user, err := a.getUserByID(ctx, userID)
	if err != nil {
		return nil, err
	}

	return &dto.MeResp{
		UserID:         user.ID,
		OpenfortUserID: user.OpenfortUserID,
		Email:          user.Email.String(),
		FirstName:      user.FirstName,
		LastName:       user.LastName,
		CompanyName:    user.CompanyName,
		PhoneNumber:    user.PhoneNumber.String(),
		Type:           user.Type.String(),
		Role:           user.Role.String(),
		Status:         user.Status.String(),
		KycVerified:    user.KycVerified,
		KybVerified:    user.KybVerified,
	}, nil
}

func (a *AuthService) AccountStatus(ctx context.Context, userID uuid.UUID) (*dto.AccountStatusResp, error) {
	user, err := a.getUserByID(ctx, userID)
	if err != nil {
		return nil, err
	}

	return &dto.AccountStatusResp{
		UserID:         user.ID,
		OpenfortUserID: user.OpenfortUserID,
		Type:           user.Type.String(),
		Role:           user.Role.String(),
		Status:         user.Status.String(),
		KycVerified:    user.KycVerified,
		KybVerified:    user.KybVerified,
		PendingKyc:     !user.KycVerified,
		PendingKyb:     user.Type == object.UserTypeOrganization && !user.KybVerified,
	}, nil
}

func (a *AuthService) KycStatus(ctx context.Context, userID uuid.UUID) (*dto.KycStatusResp, error) {
	user, err := a.getUserByID(ctx, userID)
	if err != nil {
		return nil, err
	}

	return &dto.KycStatusResp{
		UserID:        user.ID,
		Status:        user.Status.String(),
		Type:          user.Type.String(),
		KycVerified:   user.KycVerified,
		KycVerifiedAt: timePtr(user.KycVerifiedAt),
		KybVerified:   user.KybVerified,
		KybVerifiedAt: timePtr(user.KybVerifiedAt),
		PendingKyc:    !user.KycVerified,
		PendingKyb:    user.Type == object.UserTypeOrganization && !user.KybVerified,
	}, nil
}

func (a *AuthService) RefreshAccessToken(ctx context.Context, refreshToken string) (*dto.RefreshAccessTokenResp, error) {
	sess, err := a.sessRepo.GetByRefreshTokenHash(ctx, crypto.HashToken(refreshToken))
	if err != nil {
		if errs.IsNotFoundError(err) {
			return nil, errs.NewAppError(errs.Unauthorized,
				"Invalid refresh token or revoked token.", 401)
		}

		a.logger.Error("failed to get session by refresh token hash", "error", err.Error())

		return nil, errs.NewAppError(errs.Internal,
			"Failed to refresh access token.", 500)
	}

	if err = a.validateSession(sess); err != nil {
		return nil, err
	}

	user, err := a.userRepo.GetByID(ctx, sess.UserID)
	if err != nil {
		a.logger.Error("failed to get user by id", "error", err.Error())

		return nil, errs.NewAppError(errs.Internal,
			"Failed to get user.", 500)
	}

	accessToken, err := a.createToken(user.ID, sess.ID, user.KycVerified, user.KybVerified, user.Type, user.Role)
	if err != nil {
		a.logger.Error("failed to create token", "error", err.Error())

		return nil, errs.NewAppError(errs.Internal,
			"Failed to refresh access token.", 500)
	}

	if err = a.sessRepo.UpdateActivity(ctx, sess.ID, time.Now().Add(a.cfg.ActivityTimeoutDuration)); err != nil {
		a.logger.Error("failed to update session activity",
			"error", err.Error(),
			"session_id", sess.ID,
		)
	}

	a.logger.Debug("token refreshed successfully",
		"user_id", user.ID,
		"session_id", sess.ID,
	)

	return &dto.RefreshAccessTokenResp{
		Token: accessToken,
	}, nil
}

func (a *AuthService) Logout(ctx context.Context, refreshToken string) error {
	sess, err := a.sessRepo.GetByRefreshTokenHash(ctx, crypto.HashToken(refreshToken))
	if err != nil {
		if errs.IsNotFoundError(err) {
			return errs.NewAppError(errs.Unauthorized,
				"Invalid refresh token or revoked token.", 401)
		}

		a.logger.Error("failed to get session by refresh token hash", "error", err.Error())

		return errs.NewAppError(errs.Internal,
			"Failed to revoke access token.", 500)
	}

	if err = a.validateSession(sess); err != nil {
		return err
	}

	if err = a.sessRepo.RevokeByID(ctx, sess.ID, uuid.Nil, sessobj.RevocationLogout); err != nil {
		a.logger.Error("failed to revoke session", "error", err.Error())

		return errs.NewAppError(errs.Internal,
			"Failed to logout.", 500)
	}

	a.logger.Debug("user logged out",
		"user_id", sess.UserID,
		"session_id", sess.ID,
	)

	return nil
}

func (a *AuthService) DeleteAccount(ctx context.Context, userID uuid.UUID) error {
	user, err := a.getUserByID(ctx, userID)
	if err != nil {
		return err
	}

	if err = a.txn.WithinTransaction(ctx, func(txCtx context.Context) error {
		if revokeErr := a.sessRepo.RevokeAllByUserID(txCtx, userID, sessobj.RevocationUserTerminated); revokeErr != nil {
			a.logger.Error("failed to revoke user sessions during account deletion", "error", revokeErr.Error(), "user_id", userID)

			return errs.NewAppError(errs.Internal, "Failed to delete account.", 500)
		}

		if deleteErr := a.userRepo.SoftDelete(txCtx, userID); deleteErr != nil {
			a.logger.Error("failed to soft delete user", "error", deleteErr.Error(), "user_id", userID)

			return errs.NewAppError(errs.Database, "Failed to delete account.", 500)
		}

		return nil
	}); err != nil {
		return err
	}

	if err = a.openfort.DeleteUser(ctx, user.OpenfortUserID); err != nil {
		a.logger.Warn("failed to delete openfort user after local account deletion",
			"error", err.Error(),
			"user_id", userID,
			"openfort_user_id", user.OpenfortUserID,
		)
	}

	return nil
}

func (a *AuthService) createSession(
	ctx context.Context,
	userID uuid.UUID,
	audit dto.AuditReq,
) (sessID uuid.UUID, rt string, err error) {
	refreshToken, err := crypto.GenerateOpaqueToken()
	if err != nil {
		a.logger.Error("failed to generate refresh token", "error", err.Error())

		return uuid.Nil, "", errs.NewAppError(errs.Internal,
			"Failed to create session.", 500)
	}

	now := time.Now()

	sessID, err = a.sessRepo.Create(ctx, &sessentity.Session{
		UserID:            userID,
		RefreshTokenHash:  refreshToken.Hash,
		UserAgent:         audit.UserAgent,
		IPAddress:         audit.IPAddress,
		Platform:          audit.Platform,
		Browser:           audit.Browser,
		Device:            audit.Device,
		ActivityTimeoutAt: now.Add(a.cfg.ActivityTimeoutDuration),
		AbsoluteExpiredAt: now.Add(a.cfg.AbsoluteExpiresDuration),
	})
	if err != nil {
		a.logger.Error("failed to create session", "error", err.Error())

		return uuid.Nil, "", errs.NewAppError(errs.Internal,
			"Failed to create session.", 500)
	}

	return sessID, refreshToken.Plaintext, nil
}

func (a *AuthService) createToken(
	userID uuid.UUID,
	sessionID uuid.UUID,
	kycVerified, kybVerified bool,
	userType object.UserType,
	userRole object.UserRole,
) (string, error) {
	token, err := a.jwtSvc.GenerateToken(&authentity.JwtClaim{
		UserID:      userID.String(),
		SessionID:   sessionID.String(),
		KycVerified: kycVerified,
		KybVerified: kybVerified,
		Role:        userRole,
		Type:        userType,
	})
	if err != nil {
		a.logger.Error("Failed to generate token.", "error", err.Error(),
			"user_id", userID, "session_id", sessionID)

		return "", errs.NewAppError(errs.Internal,
			"Failed to generate access token.", 500)
	}

	return token, nil
}

func (a *AuthService) findOrCreateUser(
	ctx context.Context,
	req *dto.OpenfortExchangeReq,
	session *openfort.SessionResponse,
) (*userentity.User, bool, error) {
	user, err := a.userRepo.GetByOpenfortUserID(ctx, session.User.ID)
	if err == nil {
		return user, false, nil
	}

	if !errs.IsNotFoundError(err) {
		a.logger.Error("failed to get user by openfort id", "error", err.Error(), "openfort_user_id", session.User.ID)

		return nil, false, errs.NewAppError(errs.Database, "Failed to get user.", 500)
	}

	if err = validateNewUserExchange(req); err != nil {
		return nil, false, err
	}

	newUser := buildProvisionedUser(req, session)
	if err = a.validateProvisionedUser(ctx, newUser); err != nil {
		return nil, false, err
	}
	var userID uuid.UUID

	if err = a.txn.WithinTransaction(ctx, func(txCtx context.Context) error {
		createdID, createErr := a.userRepo.Create(txCtx, newUser)
		if createErr != nil {
			a.logger.Error("failed to create user", "error", createErr.Error(), "openfort_user_id", session.User.ID)

			return errs.NewAppError(errs.Database, "Failed to create user.", 500)
		}

		userID = createdID

		if newUser.Type == object.UserTypeOrganization && newUser.CompanyName != "" {
			if createErr = a.userRepo.CreateOrganization(txCtx, &userentity.Organization{
				UserID: createdID,
				Name:   newUser.CompanyName,
			}); createErr != nil {
				a.logger.Error("failed to create organization", "error", createErr.Error(), "openfort_user_id", session.User.ID)

				return errs.NewAppError(errs.Database, "Failed to create user organization.", 500)
			}
		}

		return nil
	}); err != nil {
		return nil, false, err
	}

	user, err = a.userRepo.GetByID(ctx, userID)
	if err != nil {
		a.logger.Error("failed to reload provisioned user", "error", err.Error(), "user_id", userID)

		return nil, false, errs.NewAppError(errs.Database, "Failed to get user.", 500)
	}

	return user, true, nil
}

func buildProvisionedUser(
	req *dto.OpenfortExchangeReq,
	session *openfort.SessionResponse,
) *userentity.User {
	firstName := strings.TrimSpace(req.FirstName)
	lastName := strings.TrimSpace(req.LastName)

	if firstName == "" && lastName == "" {
		firstName, lastName = splitName(session.User.Name)
	}

	email := req.Email
	if email == "" {
		email = shared.NewEmail(session.User.Email)
	}

	phone := req.PhoneNumber
	if phone == "" {
		phone = shared.NewPhoneNumber(session.User.PhoneNumber)
	}

	return &userentity.User{
		OpenfortUserID: session.User.ID,
		Email:          email,
		FirstName:      firstName,
		LastName:       lastName,
		PhoneNumber:    phone,
		CompanyName:    strings.TrimSpace(req.OrganizationName),
		Type:           normalizeUserType(req.Type),
		Role:           normalizeUserRole(req.Role),
		Status:         object.UserStatusPendingKyc,
	}
}

func normalizeUserType(userType object.UserType) object.UserType {
	switch userType {
	case object.UserTypeOrganization:
		return object.UserTypeOrganization
	case object.UserTypeIndividual:
		return object.UserTypeIndividual
	default:
		return object.UserTypeIndividual
	}
}

func normalizeUserRole(userRole object.UserRole) object.UserRole {
	switch userRole {
	case object.UserRoleProjectOwner,
		object.UserRoleContractor,
		object.UserRoleGovernance,
		object.UserRoleInvestor:
		return userRole
	case object.UserRole("client"):
		return object.UserRoleProjectOwner
	case object.UserRole("dao"):
		return object.UserRoleGovernance
	case object.UserRoleAdmin,
		object.UserRoleModerator,
		object.UserRoleSupport:
		return object.UserRoleInvestor
	default:
		return object.UserRoleInvestor
	}
}

func splitName(name string) (firstName string, lastName string) {
	parts := strings.Fields(strings.TrimSpace(name))
	if len(parts) == 0 {
		return "", ""
	}

	if len(parts) == 1 {
		return parts[0], ""
	}

	return parts[0], strings.Join(parts[1:], " ")
}

func (a *AuthService) getOpenfortSession(ctx context.Context, accessToken string) (*openfort.SessionResponse, error) {
	session, err := a.openfort.GetSession(ctx, accessToken)
	if err != nil {
		a.logger.Error("failed to validate openfort session", "error", err.Error())

		return nil, errs.NewAppError(errs.Unauthorized, "Invalid Openfort access token.", 401)
	}

	return session, nil
}

func (a *AuthService) getUserByID(ctx context.Context, userID uuid.UUID) (*userentity.User, error) {
	user, err := a.userRepo.GetByID(ctx, userID)
	if err != nil {
		if errs.IsNotFoundError(err) {
			return nil, errs.NewAppError(errs.NotFound, "User not found.", 404)
		}

		a.logger.Error("failed to get user by id", "error", err.Error(), "user_id", userID)

		return nil, errs.NewAppError(errs.Internal, "Failed to get user.", 500)
	}

	return user, nil
}

func timePtr(value time.Time) *time.Time {
	if value.IsZero() {
		return nil
	}

	return &value
}

package postgres

import (
	"context"

	"github.com/InfraFund-net7/backpro/internal/domain/shared"
	"github.com/InfraFund-net7/backpro/internal/domain/user/entity"
	"github.com/InfraFund-net7/backpro/internal/domain/user/repository"
	"github.com/InfraFund-net7/backpro/internal/infrastructure/persistence/postgres/gen"
	"github.com/InfraFund-net7/backpro/pkg/logger"
	"github.com/google/uuid"
	"github.com/jackc/pgx/v5/pgtype"
)

var _ repository.UserRepo = (*UserRepo)(nil)

type UserRepo struct {
	db     *Database
	logger *logger.SubLogger
}

func NewUserRepo(db *Database) *UserRepo {
	return &UserRepo{
		db:     db,
		logger: db.logging,
	}
}

func (u *UserRepo) Create(ctx context.Context, user *entity.User) (uuid.UUID, error) {
	u.logger.Debug("UserRepo.Create", "openfort_user_id", user.OpenfortUserID)

	id, err := u.db.Queries(ctx).CreateUser(ctx, gen.CreateUserParams{
		OpenfortUserID: user.OpenfortUserID,
		Email:          pgtype.Text{String: user.Email.String(), Valid: user.Email != ""},
		FirstName:      pgtype.Text{String: user.FirstName, Valid: user.FirstName != ""},
		LastName:       pgtype.Text{String: user.LastName, Valid: user.LastName != ""},
		PhoneNumber:    pgtype.Text{String: user.PhoneNumber.String(), Valid: user.PhoneNumber != ""},
		Type:           gen.UserType(user.Type),
		Role:           gen.UserRole(user.Role),
	})
	if err != nil {
		return uuid.Nil, err
	}

	return id, nil
}

func (u *UserRepo) CreateOrganization(ctx context.Context, org *entity.Organization) error {
	u.logger.Debug("UserRepo.CreateOrganization", "user_id", org.UserID)

	return u.db.Queries(ctx).CreateUserOrganization(ctx, gen.CreateUserOrganizationParams{
		UserID: pgtype.UUID{Bytes: org.UserID, Valid: org.UserID != uuid.Nil},
		Name:   pgtype.Text{String: org.Name, Valid: org.Name != ""},
	})
}

func (u *UserRepo) SoftDelete(ctx context.Context, userID uuid.UUID) error {
	u.logger.Debug("UserRepo.SoftDelete", "user_id", userID)

	if err := u.db.Queries(ctx).DeleteUserOrganization(ctx, pgtype.UUID{Bytes: userID, Valid: userID != uuid.Nil}); err != nil {
		return err
	}

	return u.db.Queries(ctx).SoftDeleteUser(ctx, userID)
}

func (u *UserRepo) GetByID(ctx context.Context, userID uuid.UUID) (*entity.User, error) {
	u.logger.Debug("UserRepo.GetByID", "user_id", userID)

	raw, err := u.db.Queries(ctx).GetUserByID(ctx, userID)
	if err != nil {
		return nil, err
	}

	return mapUserToDomain(raw), nil
}

func (u *UserRepo) GetByOpenfortUserID(ctx context.Context, openfortUserID string) (*entity.User, error) {
	u.logger.Debug("UserRepo.GetByOpenfortUserID", "openfort_user_id", openfortUserID)

	raw, err := u.db.Queries(ctx).GetUserByOpenfortUserID(ctx, openfortUserID)
	if err != nil {
		return nil, err
	}

	return mapUserToDomain(raw), nil
}

